    def _createSection():
        '''
        Purpose
        Asign the each part to specific section properties.
        ------------------------------------------------------------------------------------
        Return
        None
        '''
        bodies=DataModel.GetObjectsByType(DataModelObjectCategory.Body)
        mesh=DataModel.MeshDataByName(DataModel.MeshDataNames[0])
        existLinearShellElements = False
        existLinearSolidElements = False
        existQuadraticShellElements = False
        existQuadraticSolidElements = False
        shell_ids = []
        Tetra_ids = []
        Hex_ids = []
        for bo in bodies:
            if bo.Suppressed is False:
                if bo.Elements == 0:
                    try:
                        act_elapsed_sec = _act_time.time() - _ACT_START_TIME
                        log_usage("Dyna_Section_Mass", "1.0", act_elapsed_sec, 2400)
                    except:
                        pass

                    print("[UI_OUTPUT] " + str("Error:\nElement not found in part named: "+ str(bo.Name)))
                    #break
                else:
                    bg=bo.GetGeoBody()
                    bo_mesh=mesh.MeshRegionById(bg.Id)
                    el_ids=bo_mesh.ElementIds
                    node_ids=bo_mesh.NodeIds
                    #print (bo.Name)
                    #print (bg.Id)
                    if bg.BodyType.ToString() == "GeoBodySheet":
                        for element in bo_mesh.Elements:
                            elemType = element.Type
                            if elemType in (ElementTypeEnum.kTri3, ElementTypeEnum.kQuad4) and existLinearShellElements is False:
                                existLinearShellElements = True
                            elif elemType in (ElementTypeEnum.kTri6, ElementTypeEnum.kQuad8) and existQuadraticShellElements is False:
                                existQuadraticShellElements = False
                                try:
                                    act_elapsed_sec = _act_time.time() - _ACT_START_TIME
                                    log_usage("Dyna_Section_Mass", "1.0", act_elapsed_sec, 2400)
                                except:
                                    pass

                                print("[UI_OUTPUT] " + str("Error:\nQuadratic Shell Elements are found in part named: "+ str(bo.Name)))
                        if existLinearShellElements == True:
                            shell_ids.append(bg.Id)
                    elif bg.BodyType.ToString() =="GeoBodySolid":
                        tetraN = 0
                        HexN = 0
                        for element in bo_mesh.Elements:
                            elemType = element.Type
                            if str(elemType) == str(ElementTypeEnum.kTet4):
                                existLinearSolidElements = True
                                tetraN = tetraN +1
                            elif str(elemType) is str(ElementTypeEnum.kHex8):
                                existLinearSolidElements = True
                                HexN = HexN+1
                            elif elemType in (ElementTypeEnum.kTet10, ElementTypeEnum.kHex20) and existQuadraticSolidElements is False:
                                existLinearSolidElements = False
                                existQuadraticSolidElements = True
                                try:
                                    act_elapsed_sec = _act_time.time() - _ACT_START_TIME
                                    log_usage("Dyna_Section_Mass", "1.0", act_elapsed_sec, 2400)
                                except:
                                    pass

                                print("[UI_OUTPUT] " + str("Error:\nQuadratic Solid Elements are found in part named: "+ str(bo.Name)))
                        if existLinearSolidElements == True and HexN >= tetraN:
                            Hex_ids.append(bg.Id)
                        elif existLinearSolidElements == True and HexN < tetraN:
                            Tetra_ids.append(bg.Id)
        # print (shell_ids)
        # print (Tetra_ids)
        # print (Hex_ids)
        analysis = ExtAPI.DataModel.AnalysisList[0]  # Get the analysis object
        analysis.Activate()
        if len(shell_ids)>0:
            dynaSection = analysis.CreateLoadObject("Section", "LSDYNA")
            selection = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
            selection.Ids = shell_ids
            dynaSection.Properties['Geometry/DefineBy/Geo'].Value = selection
            dynaSection.Properties['Formulation'].Value = r'Fully Integrated Shell Element'
            DataModel.GetObjectById(dynaSection.ObjectId).Name = r'scr_shell_ex16'
        if len(Tetra_ids)>0:
            dynaSection = analysis.CreateLoadObject("Section", "LSDYNA")
            selection = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
            selection.Ids = Tetra_ids
            dynaSection.Properties['Geometry/DefineBy/Geo'].Value = selection
            dynaSection.Properties['Formulation'].Value = r'1 point Tetrahedron'
            DataModel.GetObjectById(dynaSection.ObjectId).Name = r'scr_tetra_ex10'
        if len(Hex_ids)>0:
            dynaSection = analysis.CreateLoadObject("Section", "LSDYNA")
            selection = ExtAPI.SelectionManager.CreateSelectionInfo(SelectionTypeEnum.GeometryEntities)
            selection.Ids = Hex_ids
            dynaSection.Properties['Geometry/DefineBy/Geo'].Value = selection
            dynaSection.Properties['Formulation'].Value = r'Poor Aspect Ratio, Fully Integrated S/R Solid , Accurate Formulation'
            DataModel.GetObjectById(dynaSection.ObjectId).Name = r'scr_hex_ex10'
        '''
        Some calls seem to be asynchronous. 
        For instance, when scoping the bodies to the CFL object, 
        it appears to still be under-defined. 
        For this reason I create a dummy comment object and 
        delete it which will update the comment object.
        '''
        temp = Model.AddComment()
        temp.Delete()

    def _showSystemWeight():
        '''
        Purpose
        Calculate the system weight, not included fixture, point mass, and distributed mass.
        ------------------------------------------------------------------------------------
        Return
        SystemWeightList: Details wieght of each part 
        SystemWeight: Total system weight
        '''
        SystemWeightList = {}
        SystemWeight = 0
        Unit = ""
        bodies = ExtAPI.DataModel.Project.Model.Geometry.GetChildren(DataModelObjectCategory.Body, True)
        for body in bodies:
            if body.Suppressed is False:
                if not re.search(r'.+fixture.?', body.Name.ToLower()):
                    mass = float(str(body.Mass).split(' ')[0])
                    unit = str(body.Mass).split(' ')[1]
                    SystemWeightList[body.Name] = mass
                    SystemWeight = SystemWeight + mass
                    SystemWeight = round(SystemWeight, 3)
        return SystemWeightList, SystemWeight, unit
   
